import {normal,coordinates,distance,clamp} from './planet.js';
const PRIORITY={birth:9,social:8,ecology:8,culture:7,mutation:7,migration:6,collective:5,death:5,court:4};
export function sphericalBlend(a,b,t){const u=normal(a.x,a.z),v=normal(b.x,b.z),dot=clamp(u.x*v.x+u.y*v.y+u.z*v.z,-1,1),angle=Math.acos(dot);if(angle<.00001)return {...b};if(dot<-.9999){const axis=Math.abs(u.y)<.9?{x:0,y:1,z:0}:{x:1,y:0,z:0},d=axis.x*u.x+axis.y*u.y+axis.z*u.z,q={x:axis.x-d*u.x,y:axis.y-d*u.y,z:axis.z-d*u.z},l=Math.hypot(q.x,q.y,q.z),c=Math.cos(Math.PI*t),s=Math.sin(Math.PI*t);return coordinates({x:u.x*c+q.x/l*s,y:u.y*c+q.y/l*s,z:u.z*c+q.z/l*s});}const s=Math.sin(angle),x=Math.sin((1-t)*angle)/s,y=Math.sin(t*angle)/s;return coordinates({x:u.x*x+v.x*y,y:u.y*x+v.y*y,z:u.z*x+v.z*y});}
export class Documentary {
 constructor({enabled=true,reducedMotion=false}={}){this.enabled=enabled;this.reducedMotion=reducedMotion;this.elapsed=0;this.resumeAt=0;this.shot=null;this.used=new Map();this.caption='La vida sigue su curso';this.status='Observando';this.nextAt=2;}
 toggle(){this.enabled=!this.enabled;this.resumeAt=0;this.nextAt=this.elapsed;this.shot=null;return this.enabled;}
 interrupt(seconds=30){this.resumeAt=this.elapsed+seconds;this.shot=null;this.nextAt=this.resumeAt;this.status='Control manual';}
 reset(){this.shot=null;this.used.clear();this.nextAt=this.elapsed+2;}
 choose(sim,world){const events=sim.events.filter(e=>PRIORITY[e.kind]&&sim.time-e.time<65&&!this.used.has('e'+e.id)).map(e=>({e,p:sim.byId.get(e.entity)||e})).filter(({p})=>Number.isFinite(p.x+p.z)).sort((a,b)=>(PRIORITY[b.e.kind]-(sim.time-b.e.time)*.06)-(PRIORITY[a.e.kind]-(sim.time-a.e.time)*.06));let chosen=events.find(({e})=>(this.used.get('c'+e.entity)??-Infinity)<this.elapsed-100)||events[0];let p,text,entity;
 if(chosen){const {e}=chosen;p=chosen.p;text=e.text;entity=e.entity;this.used.set('e'+e.id,this.elapsed);this.used.set('c'+entity,this.elapsed);}else{const living=sim.creatures.filter(c=>(this.used.get('c'+c.id)??-Infinity)<this.elapsed-100),c=living.sort((a,b)=>(b.social?.intent?4:0)+(b.ecology?.glowUntil>sim.time?3:0)+(b.pregnancy?2:0)-(a.social?.intent?4:0)-(a.ecology?.glowUntil>sim.time?3:0)-(a.pregnancy?2:0)||a.id-b.id)[0];if(c){p=c;entity=c.id;text=c.name+' · '+c.state.toLowerCase();this.used.set('c'+entity,this.elapsed);}else{p=world.focus;text='Un planeta, muchos ritmos';}}
 this.caption=text;const far=distance(world.focus,p)>14;this.shot={entity,to:{x:p.x,z:p.z},from:{...world.focus},start:this.elapsed,distance:world.desiredDistance,far,overview:!entity};this.nextAt=this.elapsed+32+(entity?entity%9:6);for(const [k,t]of this.used)if(t<this.elapsed-300)this.used.delete(k);}
 update(dt,sim,world,{paused=false,following=false}={}){this.elapsed+=Math.min(.25,dt);if(!this.enabled){this.status='Cámara libre';return;}if(following){this.interrupt(30);this.status='Siguiendo tu selección';return;}if(this.elapsed<this.resumeAt){this.status='Manual · vuelve en '+Math.ceil(this.resumeAt-this.elapsed)+' s';return;}if(paused){this.status='Tiempo en pausa';return;}this.status='Documental';if(!this.shot||this.elapsed>=this.nextAt)this.choose(sim,world);const s=this.shot,age=this.elapsed-s.start,live=sim.byId.get(s.entity);if(live)s.to={x:live.x,z:live.z};const duration=this.reducedMotion?14:9;
 if(s.far&&age<duration){const progress=clamp((age-2)/(duration-4),0,1),ease=progress*progress*(3-2*progress);world.focus=sphericalBlend(s.from,s.to,ease);world.desiredDistance=age<duration-2?Math.max(s.distance,110):24;}else{world.focus=sphericalBlend(world.focus,s.to,1-Math.exp(-dt*(this.reducedMotion?.35:.7)));world.desiredDistance=s.overview?108:18+Math.sin(age*.08)*2;}}
}
